CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, category TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', pub_date TEXT NOT NULL, tags_json TEXT NOT NULL DEFAULT '[]', body TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, desired_visibility TEXT NOT NULL CHECK (desired_visibility IN ('draft', 'published')), repo_path TEXT, base_blob_sha TEXT, published_version INTEGER, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), kind TEXT NOT NULL CHECK (kind IN ('publish', 'unpublish')), idempotency_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, snapshot_json TEXT NOT NULL, state TEXT NOT NULL, commit_sha TEXT, workflow_run_id TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS operations_active_post ON operations(post_id) WHERE state IN ('queued', 'committing', 'waiting_for_deploy', 'unknown');
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, github_user_id INTEGER NOT NULL, github_login TEXT NOT NULL, csrf_hash TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states (state_hash TEXT PRIMARY KEY, verifier TEXT NOT NULL, expires_at TEXT NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS analytics_cache (key TEXT PRIMARY KEY, payload_json TEXT NOT NULL, fetched_at TEXT NOT NULL, expires_at TEXT NOT NULL);
